    ...[0, 1].map(() => { const jong = pick(['ㄴ', 'ㄹ', 'ㅁ', 'ㅂ', 'ㅇ', 'ㄱ']); const yes = HAS_B.filter(w => w[3] === jong); if (yes.length < 2) { const y2 = HAS_B.filter(w => w[3] === 'ㄹ'); const ys = shuf(y2).slice(0, 3); const ns = others(HAS_B.filter(w => w[3] !== 'ㄹ'), [], 3); const em = {}; [...ys, ...ns].forEach(w => { em[w[1]] = w[0]; }); return Q('같은 받침 모두 고르기', { type: 'multi', prompt: '받침 ㄹ이 있는 낱말을 모두 골라요.', word: 'ㄹ', options: shuf([...ys, ...ns]).map(w => w[1]), optionEmoji: em, answer: ys.map(w => w[1]), hint: `받침 ㄹ이 있는 낱말은 ${ys.map(w => w[1]).join(', ')}이에요.` }); } const ys = shuf(yes).slice(0, Math.min(3, yes.length)); const ns = others(HAS_B.filter(w => w[3] !== jong), [], 6 - ys.length); const em = {}; [...ys, ...ns].forEach(w => { em[w[1]] = w[0]; }); return Q('같은 받침 모두 고르기', { type: 'multi', prompt: `받침 ${jong}이 있는 낱말을 모두 골라요.`, word: jong, options: shuf([...ys, ...ns]).map(w => w[1]), optionEmoji: em, answer: ys.map(w => w[1]), hint: `받침 ${jong}이 있는 낱말은 ${ys.map(w => w[1]).join(', ')}이에요.` }); }),
